import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({ defaultTags = [], onChange }: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const handleValueChange = (nextTags: string[]) => {
    setTags(nextTags);
    onChange?.(nextTags);
  };

  const handleRemove = (tagToRemove: string) => {
    const nextTags = tags.filter((tag) => tag !== tagToRemove);
    setTags(nextTags);
    onChange?.(nextTags);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-sm)' }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={handleValueChange}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-xs)' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => handleRemove(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

